-- Demo seed for module crm (E9). Synthetic data only (names marked Demo, emails @demo.invalid).
-- Generated; idempotent; runs as the schema owner after the core demo seed. FORCE RLS is lifted only on the crm
-- tables for the duration of the seed and restored at the end. No claims are bound, so the crm triggers skip
-- validation and auditing (system path); stage_change activities are written explicitly below.
DO $seed$ BEGIN
IF NOT EXISTS (SELECT 1 FROM app.organization WHERE id = 'a0000000-0000-4000-8000-000000000001') THEN RETURN; END IF;
IF EXISTS (SELECT 1 FROM app.lead WHERE id = 'a0000000-0000-4000-8008-000000000001') THEN RETURN; END IF;
ALTER TABLE app.lead NO FORCE ROW LEVEL SECURITY;
ALTER TABLE app.lead_activity NO FORCE ROW LEVEL SECURITY;
ALTER TABLE app.crm_task NO FORCE ROW LEVEL SECURITY;
ALTER TABLE app.lead FORCE ROW LEVEL SECURITY;
ALTER TABLE app.lead_activity FORCE ROW LEVEL SECURITY;
ALTER TABLE app.crm_task FORCE ROW LEVEL SECURITY;
END $seed$;
